import openpyxl
wb = openpyxl.load_workbook('output.xlsx')
for name in wb.sheetnames:
    ws = wb[name]
    print('SHEET', name, ws.dimensions)
    for row in ws.iter_rows():
        for c in row:
            if c.value is not None or c.has_style:
                f=c.fill
                b=c.border
                print(c.coordinate, 'val=',repr(c.value), 'fill=',f.fgColor.rgb if f.patternType else None, 'border=', b.left.style, b.right.style, b.top.style, b.bottom.style)
